/**
 * Vector3 utility class for 3D math operations
 */
export class Vector3 {
  constructor(x = 0, y = 0, z = 0) {
    this.x = x;
    this.y = y;
    this.z = z;
  }

  clone() {
    return new Vector3(this.x, this.y, this.z);
  }

  add(v) {
    return new Vector3(this.x + v.x, this.y + v.y, this.z + v.z);
  }

  subtract(v) {
    return new Vector3(this.x - v.x, this.y - v.y, this.z - v.z);
  }

  multiply(scalar) {
    return new Vector3(this.x * scalar, this.y * scalar, this.z * scalar);
  }

  divide(scalar) {
    if (scalar === 0) throw new Error('Division by zero');
    return new Vector3(this.x / scalar, this.y / scalar, this.z / scalar);
  }

  dot(v) {
    return this.x * v.x + this.y * v.y + this.z * v.z;
  }

  cross(v) {
    return new Vector3(
      this.y * v.z - this.z * v.y,
      this.z * v.x - this.x * v.z,
      this.x * v.y - this.y * v.x
    );
  }

  length() {
    return Math.sqrt(this.x * this.x + this.y * this.y + this.z * this.z);
  }

  normalize() {
    const len = this.length();
    if (len === 0) return new Vector3(0, 0, 0);
    return this.divide(len);
  }

  distanceTo(v) {
    return this.subtract(v).length();
  }

  lerp(target, t) {
    return new Vector3(
      this.x + (target.x - this.x) * t,
      this.y + (target.y - this.y) * t,
      this.z + (target.z - this.z) * t
    );
  }

  clamp(min, max) {
    return new Vector3(
      Math.max(Math.min(this.x, max), min),
      Math.max(Math.min(this.y, max), min),
      Math.max(Math.min(this.z, max), min)
    );
  }

  scale(x = 1, y = 1, z = 1) {
    return new Vector3(this.x * x, this.y * y, this.z * z);
  }

  toThreeJSVector() {
    return new THREE.Vector3(this.x, this.y, this.z);
  }

  fromThreeJSVector(v) {
    return new Vector3(v.x, v.y, v.z);
  }

  toString() {
    return `Vector3(${this.x.toFixed(2)}, ${this.y.toFixed(2)}, ${this.z.toFixed(2)})`;
  }
}

/**
 * Matrix utilities for transformations
 */
export class Matrix4x4 {
  constructor(x = 0, y = 0, z = 0, w = 1) {
    this.x = x;
    this.y = y;
    this.z = z;
    this.w = w;
  }

  clone() {
    return new Matrix4x4(this.x, this.y, this.z, this.w);
  }

  multiply(other) {
    if (other instanceof Matrix4x4) {
      const result = new Matrix4x4(0, 0, 0, 1);
      // Simplified multiplication for translation matrices
      result.x = this.x * other.x + this.y * other.z;
      result.y = this.y * other.y + this.z * other.w;
      result.z = this.z * other.z + this.w * other.w;
      return result;
    }
    throw new Error('Matrix multiplication requires another Matrix4x4');
  }

  toThreeJSMatrix() {
    const m = new THREE.Matrix4();
    m.set(this.x, 0, 0, 1);
    m.set(0, this.y, 0, 1);
    m.set(0, 0, this.z, 1);
    return m;
  }

  toString() {
    return `Matrix4x4(${this.x.toFixed(2)}, ${this.y.toFixed(2)}, ${this.z.toFixed(2)})`;
  }
}

/**
 * Utility functions for common math operations
 */
export const clamp = (value, min, max) => Math.max(min, Math.min(max, value));
export const lerp = (a, b, t) => a + (b - a) * t;
export const easeOutCubic = (t) => 1 - Math.pow(1 - t, 3);
export const easeInQuart = (t) => 1 - Math.pow(1 - t, 4);

/**
 * Generate random number within range [min, max]
 */
export function rand(min, max) {
  return min + Math.random() * (max - min);
}

/**
 * Generate random integer within range [min, max] inclusive
 */
export function randInt(min, max) {
  return Math.floor(rand(min, max + 1));
}

/**
 * Check if two AABBs collide
 * @param {Object} a - First box: {x, y, z, w, h, d}
 * @param {Object} b - Second box: {x, y, z, w, h, d}
 * @returns {boolean}
 */
export function aabbCollides(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y &&
    a.z < b.z + b.d &&
    a.z + a.d > b.z
  );
}

/**
 * Check if two spheres collide
 * @param {Object} a - First sphere: {x, y, z, r}
 * @param {Object} b - Second sphere: {x, y, z, r}
 * @returns {boolean}
 */
export function sphereCollides(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  const dz = a.z - b.z;
  return (dx * dx + dy * dy + dz * dz) < (a.r + b.r) * (a.r + b.r);
}

/**
 * Check if two circles collide (2D)
 * @param {Object} a - First circle: {x, y, r}
 * @param {Object} b - Second circle: {x, y, r}
 * @returns {boolean}
 */
export function circleCollides(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return (dx * dx + dy * dy) < (a.r + b.r) * (a.r + b.r);
}

/**
 * Check if two rectangles collide (2D axis-aligned)
 * @param {Object} a - First rect: {x, y, w, h}
 * @param {Object} b - Second rect: {x, y, w, h}
 * @returns {boolean}
 */
export function rectCollides(a, b) {
  return (
    a.x < b.x + b.w &&
    a.x + a.w > b.x &&
    a.y < b.y + b.h &&
    a.y + a.h > b.y
  );
}

/**
 * Generate simplex noise using value-based approach
 */
export function simplexNoise(x, y, z = 0) {
  // Normalize coordinates to [0, 1] range for consistent noise
  const scale = 2.0;
  const nx = x * scale;
  const ny = y * scale;
  const nz = z * scale;

  // Get grid positions
  const ix = Math.floor(nx);
  const iy = Math.floor(ny);
  const iz = Math.floor(nz);

  // Fractional parts
  const fx = nx - ix;
  const fy = ny - iy;
  const fz = nz - iz;

  // Smoothstep function
  function smoothstep(t) {
    return t * t * (3 - 2 * t * t);
  }

  // Hash function for grid positions
  function hash(x, y, z) {
    let h = x + y + z;
    h = Math.sin(h * 12.9898) * 43758.5453;
    return h - Math.floor(h);
  }

  // Get noise value for a grid point
  function getNoise(x, y, z) {
    const hx = hash(Math.floor(x), Math.floor(y), Math.floor(z));
    const hy = hash(Math.floor(x + 1), Math.floor(y), Math.floor(z));
    const hz = hash(Math.floor(x), Math.floor(y + 1), Math.floor(z));
    const hh = hash(Math.floor(x + 1), Math.floor(y + 1), Math.floor(z));

    // Interpolate in x
    const n00 = smoothstep(fx) * hx + (1 - smoothstep(fx)) * hy;
    const n10 = smoothstep(fx) * hz + (1 - smoothstep(fx)) * hh;

    // Interpolate in y
    return smoothstep(fy) * n00 + (1 - smoothstep(fy)) * n10;
  }

  // Get noise value for a grid point with z offset
  function getNoiseZ(x, y, z) {
    const hx = hash(Math.floor(x), Math.floor(y), Math.floor(z));
    const hy = hash(Math.floor(x + 1), Math.floor(y), Math.floor(z));
    const hz = hash(Math.floor(x), Math.floor(y + 1), Math.floor(z));
    const hh = hash(Math.floor(x + 1), Math.floor(y + 1), Math.floor(z));

    // Interpolate in x
    const n00 = smoothstep(fx) * hx + (1 - smoothstep(fx)) * hy;
    const n10 = smoothstep(fx) * hz + (1 - smoothstep(fx)) * hh;

    // Interpolate in y
    const n01 = smoothstep(fy) * n00 + (1 - smoothstep(fy)) * n10;

    // Interpolate in z
    return smoothstep(fz) * n01 + (1 - smoothstep(fz)) * getNoiseZ(x, y, z + 1);
  }

  // Octave summation for fractal noise
  let result = 0;
  let amplitude = 1.0;
  let frequency = 1.0;
  const octaves = 4;

  for (let i = 0; i < octaves; i++) {
    result += getNoiseZ(nx, ny, nz) * amplitude;
    amplitude *= 0.5;
    frequency *= 2;
  }

  return result;
}

/**
 * Generate Perlin noise using gradient-based approach
 */
export function perlinNoise(x, y, z = 0) {
  // Gradient vectors (normalized)
  const gradients = [
    new Vector3(1, 0, 0), new Vector3(-1, 0, 0),
    new Vector3(0, 1, 0), new Vector3(0, -1, 0),
    new Vector3(0, 0, 1), new Vector3(0, 0, -1),
    new Vector3(1, 1, 0), new Vector3(-1, 1, 0),
    new Vector3(1, -1, 0), new Vector3(-1, -1, 0),
    new Vector3(1, 0, 1), new Vector3(-1, 0, 1),
    new Vector3(1, 0, -1), new Vector3(-1, 0, -1),
    new Vector3(0, 1, 1), new Vector3(0, -1, 1),
    new Vector3(0, 1, -1), new Vector3(0, -1, -1)
  ];

  // Normalize gradients
  const normalizedGradients = gradients.map(g => {
    const len = g.length();
    return new Vector3(g.x / len, g.y / len, g.z / len);
  });

  // Hash function for grid positions
  function hash(x, y, z) {
    let h = x + y + z;
    h = Math.sin(h * 12.9898) * 43758.5453;
    return h - Math.floor(h);
  }

  // Smoothstep function
  function smoothstep(t) {
    return t * t * (3 - 2 * t * t);
  }

  // Get gradient dot product
  function getGradientDot(g, x, y, z) {
    const gx = hash(x, y, z);
    const gy = hash(x + 1, y, z);
    const gz = hash(x, y + 1, z);
    const hh = hash(x + 1, y + 1, z);

    // Interpolate in x
    const n00 = smoothstep(gx) * gx + (1 - smoothstep(gx)) * gy;
    const n10 = smoothstep(gx) * gz + (1 - smoothstep(gx)) * hh;

    // Interpolate in y
    return smoothstep(gy) * n00 + (1 - smoothstep(gy)) * n10;
  }

  // Octave summation for fractal noise
  let result = 0;
  let amplitude = 1.0;
  const octaves = 4;

  for (let i = 0; i < octaves; i++) {
    const nx = x * 2 ** i;
    const ny = y * 2 ** i;
    const nz = z * 2 ** i;

    // Get gradient dot product for each octave
    let gradDot = 0;
    for (let j = 0; j < normalizedGradients.length; j++) {
      const g = normalizedGradients[j];
      const dot = g.x * nx + g.y * ny + g.z * nz;
      if (dot > 0) gradDot += dot;
    }

    // Normalize and add to result
    result += (gradDot / normalizedGradients.length) * amplitude;
    amplitude *= 0.5;
  }

  return result;
}

/**
 * Generate noise-based displacement for geometry
 */
export function generateDisplacement(x, y, z = 0, frequency = 1, amplitude = 1) {
  const nx = simplexNoise(x * frequency, y * frequency);
  const ny = simplexNoise(y * frequency, x * frequency);
  return (nx + ny) * amplitude;
}

/**
 * Generate noise-based heightmap for terrain
 */
export function generateHeightmap(width, height, frequency = 1, amplitude = 1) {
  const map = [];
  for (let y = 0; y < height; y++) {
    const row = [];
    for (let x = 0; x < width; x++) {
      row.push(generateDisplacement(x / width * 10, y / height * 10, frequency, amplitude));
    }
    map.push(row);
  }
  return map;
}

/**
 * Generate noise-based color gradient for materials
 */
export function generateColorGradient(t) {
  // Smooth transition between colors using HSL interpolation
  const hue = t * 360;
  const saturation = 80 + Math.sin(t * 2 * Math.PI) * 20;
  const lightness = 50 + Math.cos(t * 1.5 * Math.PI) * 10;
  return `hsl(${hue}, ${saturation}%, ${lightness}%)`;
}

/**
 * Generate procedural texture data for Canvas API
 */
export function generateTextureData(width, height, type = 'grid') {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  if (type === 'grid') {
    // Grid pattern with neon lines
    ctx.strokeStyle = 'rgba(0, 255, 255, 0.3)';
    ctx.lineWidth = 1;
    for (let x = 0; x <= width; x += 40) {
      ctx.beginPath();
      ctx.moveTo(x, 0);
      ctx.lineTo(x, height);
      ctx.stroke();
    }
    for (let y = 0; y <= height; y += 40) {
      ctx.beginPath();
      ctx.moveTo(0, y);
      ctx.lineTo(width, y);
      ctx.stroke();
    }
  } else if (type === 'noise') {
    // Noise pattern using simplex noise
    for (let y = 0; y < height; y++) {
      for (let x = 0; x < width; x++) {
        const value = simplexNoise(x / width * 5, y / height * 5) * 128 + 64;
        ctx.fillStyle = `rgb(${value}, ${value * 0.7}, ${value * 0.3})`;
        ctx.fillRect(x, y, 1, 1);
      }
    }
  } else if (type === 'gradient') {
    // Gradient pattern
    const gradient = ctx.createLinearGradient(0, 0, width, height);
    gradient.addColorStop(0, 'rgba(0, 255, 255, 0.1)');
    gradient.addColorStop(0.5, 'rgba(255, 0, 255, 0.1)');
    gradient.addColorStop(1, 'rgba(0, 255, 255, 0.1)');
    ctx.fillStyle = gradient;
    ctx.fillRect(0, 0, width, height);
  }

  return canvas;
}

/**
 * Generate procedural mesh geometry using noise displacement
 */
export function generateProceduralMesh(width, height, segmentsPerSide = 20) {
  const vertices = [];
  const indices = [];

  for (let i = 0; i <= segmentsPerSide; i++) {
    for (let j = 0; j <= segmentsPerSide; j++) {
      const x = (i / segmentsPerSide - 0.5) * width;
      const y = (j / segmentsPerSide - 0.5) * height;
      const z = generateDisplacement(x, y);

      vertices.push({ x, y, z });
    }
  }

  for (let i = 0; i < segmentsPerSide; i++) {
    for (let j = 0; j < segmentsPerSide - 1; j++) {
      const a = i * (segmentsPerSide + 1) + j;
      const b = a + 1;
      const c = (i + 1) * (segmentsPerSide + 1) + j;
      const d = c + 1;

      indices.push(a, b, c);
      indices.push(a, d, c);
    }
  }

  return { vertices, indices };
}

/**
 * Generate procedural particle system configuration
 */
export function generateParticleConfig(type) {
  switch (type) {
    case 'spark':
      return {
        count: 20,
        speedRange: [50, 300],
        lifeRange: [0.3, 1.0],
        sizeRange: [2, 8],
        color: '#ffffff',
        gravity: -500
      };
    case 'explosion':
      return {
        count: 50,
        speedRange: [100, 600],
        lifeRange: [0.5, 2.0],
        sizeRange: [3, 15],
        color: '#ffaa00',
        gravity: -800
      };
    case 'trail':
      return {
        count: 1,
        speedRange: [0, 0],
        lifeRange: [0.2, 0.3],
        sizeRange: [5, 10],
        color: '#00ffff',
        gravity: 0
      };
    case 'shockwave':
      return {
        count: 0, // Special ring effect
        speedRange: [200, 300],
        lifeRange: [1.0, 1.5],
        sizeRange: [10, 80],
        color: '#ff00ff',
        gravity: 0
      };
    default:
      return {
        count: 10,
        speedRange: [50, 200],
        lifeRange: [0.3, 0.8],
        sizeRange: [2, 6],
        color: '#ffffff',
        gravity: -300
      };
  }
}

/**
 * Generate procedural sound frequency for Web Audio API
 */
export function generateSoundFrequency(type) {
  switch (type) {
    case 'laser': return 800 + Math.random() * 400;
    case 'explosion': return 150 + Math.random() * 200;
    case 'enemyDeath': return 300 + Math.random() * 200;
    case 'playerHit': return 600 + Math.random() * 400;
    case 'powerUp': return 1200 + Math.random() * 800;
    default: return 400 + Math.random() * 300;
  }
}

/**
 * Generate procedural enemy sprite data for Canvas API
 */
export function generateEnemySpriteData(row) {
  const width = 32;
  const height = 32;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Base colors for each row
  const colors = [
    '#ff00ff', // Row 0: Purple (squid-like)
    '#00ffff', // Row 1: Cyan (crab-like)
    '#00ff88', // Row 2: Green (octopus-like)
    '#00cc00', // Row 3: Dark green
    '#ffaa00'  // Row 4: Amber
  ];

  const color = colors[row % colors.length];

  ctx.fillStyle = color;

  if (row === 0) {
    // Squid-like shape for top row
    ctx.beginPath();
    ctx.ellipse(16, 8, 12, 4, 0, Math.PI * 2, 0);
    ctx.fill();
    ctx.fillRect(8, 12, 24, 16);
    ctx.fillRect(12, 16, 20, 8);
    ctx.fillRect(10, 20, 24, 4);
    ctx.fillRect(14, 24, 20, 4);
  } else if (row === 1) {
    // Crab-like shape for second row
    ctx.beginPath();
    ctx.ellipse(16, 8, 10, 3, 0, Math.PI * 2, 0);
    ctx.fill();
    ctx.fillRect(6, 10, 28, 14);
    ctx.fillRect(4, 14, 28, 12);
    ctx.fillRect(2, 18, 30, 6);
    ctx.fillRect(12, 22, 20, 6);
  } else if (row === 2) {
    // Octopus-like shape for third row
    ctx.beginPath();
    ctx.ellipse(16, 8, 14, 5, 0, Math.PI * 2, 0);
    ctx.fill();
    ctx.fillRect(8, 12, 24, 14);
    ctx.fillRect(6, 16, 28, 10);
    ctx.fillRect(4, 20, 32, 6);
    ctx.fillRect(10, 24, 24, 4);
  } else if (row === 3) {
    // Turtle-like shape for fourth row
    ctx.beginPath();
    ctx.ellipse(16, 8, 12, 4, 0, Math.PI * 2, 0);
    ctx.fill();
    ctx.fillRect(8, 12, 24, 14);
    ctx.fillRect(6, 16, 28, 10);
    ctx.fillRect(4, 20, 32, 6);
    ctx.fillRect(14, 24, 20, 4);
  } else {
    // Alien-like shape for bottom row
    ctx.beginPath();
    ctx.ellipse(16, 8, 10, 3, 0, Math.PI * 2, 0);
    ctx.fill();
    ctx.fillRect(8, 12, 24, 14);
    ctx.fillRect(6, 16, 28, 10);
    ctx.fillRect(4, 20, 32, 6);
    ctx.fillRect(12, 24, 20, 4);
  }

  return canvas;
}

/**
 * Generate procedural player sprite data for Canvas API
 */
export function generatePlayerSpriteData() {
  const width = 32;
  const height = 32;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Player ship shape (neon blue)
  ctx.fillStyle = '#00ffff';

  // Main body
  ctx.beginPath();
  ctx.moveTo(16, 4);
  ctx.lineTo(30, 28);
  ctx.lineTo(16, 24);
  ctx.lineTo(2, 28);
  ctx.closePath();
  ctx.fill();

  // Cockpit
  ctx.fillStyle = '#aaffff';
  ctx.beginPath();
  ctx.moveTo(16, 8);
  ctx.lineTo(20, 22);
  ctx.lineTo(16, 24);
  ctx.lineTo(12, 22);
  ctx.closePath();
  ctx.fill();

  // Engine glow
  ctx.fillStyle = '#00ffaa';
  ctx.fillRect(12, 28, 20, 4);

  return canvas;
}

/**
 * Generate procedural power-up sprite data for Canvas API
 */
export function generatePowerUpSpriteData(type) {
  const width = 32;
  const height = 32;
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Power-up colors based on type
  const colors = {
    wideShot: '#00ffaa',   // Green for wide shot
    shield: '#aaff00',     // Yellow for shield
    rapidFire: '#ff44aa'   // Pink for rapid fire
  };

  const color = colors[type] || '#ffffff';

  ctx.fillStyle = color;

  // Power-up shape (diamond)
  ctx.beginPath();
  ctx.moveTo(16, 4);
  ctx.lineTo(30, 16);
  ctx.lineTo(16, 28);
  ctx.lineTo(2, 16);
  ctx.closePath();
  ctx.fill();

  // Inner glow
  ctx.fillStyle = 'rgba(255, 255, 255, 0.5)';
  ctx.beginPath();
  ctx.moveTo(16, 8);
  ctx.lineTo(24, 16);
  ctx.lineTo(16, 24);
  ctx.lineTo(8, 16);
  ctx.closePath();
  ctx.fill();

  // Type indicator
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.font = '10px Arial';
  ctx.textAlign = 'center';
  ctx.fillText(type.charAt(0).toUpperCase(), 16, 20);

  return canvas;
}

/**
 * Generate procedural background starfield data for Canvas API
 */
export function generateStarfieldData(count = 50) {
  const stars = [];
  for (let i = 0; i < count; i++) {
    stars.push({
      x: Math.random() * 1920,
      y: Math.random() * 1080,
      size: Math.random() * 2 + 0.5,
      brightness: Math.random() * 0.5 + 0.3,
      twinkleSpeed: Math.random() * 0.02 + 0.01,
      twinkleOffset: Math.random() * Math.PI * 2
    });
  }
  return stars;
}

/**
 * Generate procedural particle system for explosions
 */
export function generateExplosionParticles(count = 50) {
  const particles = [];
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = rand(100, 600);
    particles.push({
      x: 0,
      y: 0,
      z: 0,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: rand(0.5, 2.0),
      maxLife: rand(0.5, 2.0),
      size: rand(3, 15),
      color: `hsl(${rand(0, 60)}, ${rand(70, 100)}%, ${rand(40, 80)}%)`
    });
  }
  return particles;
}

/**
 * Generate procedural particle system for player death explosion
 */
export function generateDeathParticles(count = 80) {
  const particles = [];
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = rand(150, 600);
    particles.push({
      x: 0,
      y: 0,
      z: 0,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: rand(0.8, 3.0),
      maxLife: rand(0.8, 3.0),
      size: rand(4, 20),
      color: `hsl(${rand(180, 270)}, ${rand(60, 90)}%, ${rand(50, 80)}%)`
    });
  }
  return particles;
}

/**
 * Generate procedural particle system for power-up pickup
