 */
export function generateHitParticles(count = 15) {
  const particles = [];
  for (let i = 0; i < count; i++) {
    const angle = Math.random() * Math.PI * 2;
    const speed = rand(50, 200);
    particles.push({
      x: 0,
      y: 0,
      z: 0,
      vx: Math.cos(angle) * speed,
      vy: Math.sin(angle) * speed,
      life: rand(0.1, 0.5),
      maxLife: rand(0.1, 0.5),
      size: rand(2, 6),
      color: `hsl(${rand(0, 30)}, ${rand(80, 100)}%, ${rand(70, 90)}%)`
    };
  }
  return particles;
}

